create role authenticated; create role anon; create schema auth; create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.uid',true),'')::uuid$$;
create table dining_areas(id uuid,tenant_id uuid,venue_id uuid,name text,sort_order numeric,is_active boolean,canvas_width numeric,canvas_height numeric,map_elements jsonb,created_at timestamptz,updated_at timestamptz);
create table restaurant_tables(id uuid,tenant_id uuid,venue_id uuid,area_id uuid,cash_session_id uuid,name text,capacity numeric,shape text,position_x numeric,position_y numeric,width numeric,height numeric,is_active boolean,sort_order numeric,reserved_until timestamptz,reservation_note text,created_at timestamptz,updated_at timestamptz);
create table orders(id uuid,tenant_id uuid,venue_id uuid,cash_session_id uuid,cash_register_id uuid,opened_by_user_id uuid,opened_by_device_id uuid,guest_count numeric,status text,revision numeric,order_group_id uuid,split_sequence numeric,draft_discount jsonb,opened_at timestamptz,updated_at timestamptz,closed_at timestamptz);
create table order_lines(id uuid,tenant_id uuid,venue_id uuid,order_id uuid,product_id uuid,variant_id uuid,product_name text,variant_name text,unit_price_cents numeric,quantity numeric,served_quantity numeric,fully_served_at timestamptz,modifiers jsonb,components jsonb,catalog_snapshot jsonb,mixer_product_id uuid,mixer jsonb,note text,created_at timestamptz,updated_at timestamptz);
create table venues(id uuid,tenant_id uuid,timezone text); create table cash_sessions(id uuid,tenant_id uuid,venue_id uuid,status text); create table cash_registers(id uuid,tenant_id uuid,venue_id uuid,name text);
create table order_tables(order_id uuid,order_group_id uuid,table_id uuid,tenant_id uuid,venue_id uuid,joined_at timestamptz,released_at timestamptz); create table restaurant_order_equal_splits(tenant_id uuid,venue_id uuid,order_group_id uuid,paid_cents numeric,status text); create table reservations(id uuid,tenant_id uuid,venue_id uuid,customer_name text,customer_phone text,party_size integer,starts_at timestamptz,ends_at timestamptz,status text); create table reservation_tables(tenant_id uuid,venue_id uuid,table_id uuid,reservation_id uuid); create table production_line_allocations(tenant_id uuid,venue_id uuid,current_order_line_id uuid,ready_quantity numeric);
create table fiscal_sif_installations(id uuid,tenant_id uuid,venue_id uuid,cash_register_id uuid,device_id uuid,fiscal_subject_id uuid,retired_at timestamptz); create table fiscal_subjects(id uuid,tenant_id uuid,legal_name text,nif text); create table fiscal_pos_bridge_settings(tenant_id uuid); create table fiscal_local_records(id uuid,tenant_id uuid,fiscal_subject_id uuid,installation_id uuid,chain_position integer);
create function get_cash_session_table_layout(uuid) returns jsonb language sql as $$select jsonb_build_object('cashSessionId',$1,'revision',0,'tables','{}'::jsonb)$$;